mapper.select:
SELECT e.from_stage_code AS fromStageCode,
       e.to_stage_code AS toStageCode,
       COUNT(*) AS eventCount
FROM crm_lead_stage_event e
INNER JOIN crm_lead l ON l.id = e.lead_id
WHERE e.tenant_id = #{ctx.tenantId}
  AND e.deleted = 0
  AND e.occurred_at >= #{ctx.startTime}
  AND e.occurred_at < #{ctx.endTimeExclusive}

GROUP BY e.from_stage_code, e.to_stage_code

SELECT u.id, COALESCE(NULLIF(u.nickname,''), u.username) AS name, u.dept_id AS deptId, d.dept_name AS deptName FROM sys_user u LEFT JOIN sys_dept d ON d.id = u.dept_id AND d.deleted = 0 WHERE u.tenant_id = #{ctx.tenantId} AND u.deleted = 0 AND EXISTS ( SELECT 1 FROM crm_lead l0 WHERE l0.tenant_id = #{ctx.tenantId} AND l0.deleted = 0 AND l0.owner_id = u.id UNION ALL SELECT 1 FROM biz_order o0 WHERE o0.tenant_id = #{ctx.tenantId} AND o0.deleted = 0 AND o0.salesman_id = u.id )
AND u.dept_id IN #{deptId}
AND u.id = #{ctx.userId} AND u.dept_id = #{ctx.deptId} ORDER BY d.sort, u.id

SELECT d.id, d.dept_name AS name FROM sys_dept d WHERE d.tenant_id = #{ctx.tenantId} AND d.deleted = 0
AND d.id IN #{deptId}
AND d.id = #{ctx.currentDeptId} ORDER BY d.sort, d.id

SELECT q.leadId, q.companyName, q.ownerId, q.ownerName, q.deptId, q.deptName, q.stageCode, CASE q.stageCode WHEN 'LEAD_RECEIVED' THEN '线索接收' WHEN 'NEEDS_COMMUNICATION' THEN '需求沟通' WHEN 'NEEDS_CLARIFICATION' THEN '需求答疑' WHEN 'SIGNING_PAYMENT' THEN '签单收款' WHEN 'HANDOFF_DELIVERY' THEN '移交结束交付' END AS stageName, q.stageEnteredAt, DATEDIFF(CURDATE(), DATE(COALESCE(q.stageEnteredAt, q.createTime))) AS stageAgeDays, q.nextActionType, q.nextActionTime, q.lastFollowTime, q.expectedAmount, CASE WHEN q.nextActionTime < #{ctx.now} THEN TRUE ELSE FALSE END AS overdue, q.customerLevel FROM ( SELECT l.id AS leadId, l.company AS companyName, l.owner_id AS ownerId, COALESCE(NULLIF(u.nickname,''), u.username) AS ownerName, l.dept_id AS deptId, d.dept_name AS deptName, CASE WHEN l.status = 3 THEN 'HANDOFF_DELIVERY' WHEN l.follow_status = '线索接收' THEN 'LEAD_RECEIVED' WHEN l.follow_status = '需求沟通' THEN 'NEEDS_COMMUNICATION' WHEN l.follow_status = '需求答疑' THEN 'NEEDS_CLARIFICATION' WHEN l.follow_status = '签单收款' THEN 'SIGNING_PAYMENT' WHEN l.follow_status = '移交结束交付' THEN 'HANDOFF_DELIVERY' WHEN l.status = 2 THEN 'NEEDS_COMMUNICATION' ELSE 'LEAD_RECEIVED' END AS stageCode, se.stageEnteredAt, l.create_time AS createTime, l.next_action_type AS nextActionType, COALESCE(l.next_action_time, TIMESTAMP(l.next_follow_time)) AS nextActionTime, l.last_follow_time AS lastFollowTime, COALESCE(l.deal_amount, l.quoted_price, 0) AS expectedAmount, COALESCE(NULLIF(l.intent_level, ''), l.customer_level) AS customerLevel FROM crm_lead l LEFT JOIN sys_user u ON u.id = l.owner_id AND u.deleted = 0 LEFT JOIN sys_dept d ON d.id = l.dept_id AND d.deleted = 0 LEFT JOIN ( SELECT lead_id, MAX(occurred_at) AS stageEnteredAt FROM crm_lead_stage_event WHERE tenant_id = #{ctx.tenantId} AND deleted = 0 AND to_stage_code = #{stageCode} GROUP BY lead_id ) se ON se.lead_id = l.id WHERE l.status IN (1,2,3)
) q WHERE q.stageCode = #{stageCode}
AND (q.companyName LIKE CONCAT('%', #{keyword}, '%') OR q.ownerName LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY CASE WHEN q.nextActionTime < #{ctx.now} THEN 0 ELSE 1 END, q.nextActionTime, q.stageEnteredAt, q.leadId DESC
